def _hull_idx(P):
    """Vertex indices of the convex hull (monotone chain). Used to
    enumerate hull-edge lines for the reflection escape moves."""
    order = np.lexsort((P[:, 1], P[:, 0]))

    def half(ids):
        h = []
        for i in ids:
            while len(h) >= 2:
                ox, oy = P[h[-2]]
                nx, ny = P[h[-1]]
                px, py = P[i]
                if (nx - ox) * (py - oy) - (ny - oy) * (px - ox) <= 1e-15:
                    h.pop()
                else:
                    break
            h.append(i)
        return h

    hull = half(order)[:-1] + half(order[::-1])[:-1]
    if len(hull) < 3:
        hull = list(range(P.shape[0]))
    return np.array(hull, dtype=int)


